import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n == 0:
        print("Memory Released.")
        return

    patient_ids = list(map(int, data[1:1+n]))
    conditions = list(map(int, data[1+n:1+2*n]))

    room_ranges = {
        0: 101,
        1: 201,
        2: 301
    }

    rooms = []
    for cond in conditions:
        base_room = room_ranges.get(cond, 101)
        rooms.append(base_room)

    for i in range(n):
        print(f"Patient ID {patient_ids[i]} is assigned Room {rooms[i]}")

    print("Memory Released.")

if __name__ == "__main__":
    main()
